import { criteria, people } from './data.js';
import { S,esc,icon,link,button,badge,photo,banner,tabs,field,select,search,filters,heading,empty,workspace,table,row,cardTitle,projectCell,metrics,date,publicPage } from './ui.js';
import { currentProject } from './account.js';
const cfg=()=>S.config.criteria?.length?S.config.criteria:criteria;
const more=(p,action='project-details')=>button('Открыть →',action,'sm',`data-id="${p.id}"`);
const map=()=>`<div class="map-card">${photo('map','Демонстрационная карта регионов')}<div class="map-legend">${['Более 200','100 – 200','50 – 100','10 – 50','Менее 10'].map((t,i)=>`<div><i style="opacity:${1-i*.17}"></i>${t}</div>`).join('')}</div></div>`;
const projectRows=()=>S.projects.map(p=>row([projectCell(p),esc(p.nomination),badge(p.status),esc(p.experts?.length?'Назначен ('+p.experts.length+')':'Не назначены'),badge('Проверено'),date(p.created),p.status==='На проверке'?`<div class="spaced">${button('Допустить','admit','mint sm',`data-id="${p.id}"`)}${button('Отклонить','reject','danger sm',`data-id="${p.id}"`)}</div>`:more(p)],`data-item data-category="${p.status}" data-meta="${esc(p.nomination)}"`)).join('');
export const contentTable=(mode=0)=>table(['Название','Раздел','Статус','Действия'],(mode===0?S.pages:S.news).map(n=>row([esc(n.title),mode===0?'Основные':'Новости',badge(n.published?'Опубликовано':'Черновик'),button(icon('edit'),'edit-content','sm',`data-kind="${mode===0?'page':'news'}" data-id="${n.id}"`)],`data-item data-category="${n.published?'Опубликовано':'Черновик'}"`)));
const userRoleTabs=()=>'<div class="role-tabs">'+[['Все',''],['Участники','participant'],['Педагоги','teacher'],['Эксперты','expert'],['Комиссия','commission'],['Администраторы','admin'],['Партнёры','partner']].map(([label,role],i)=>'<button type="button" data-action="user-role-tab" data-role="'+role+'" class="'+(i===0?'active':'')+'">'+label+'<span>'+(role?S.users.filter(u=>u.role===role).length:S.users.length)+'</span></button>').join('')+'</div>';
export const adminPages={
 ranking:()=>{const ranked=[...S.projects].sort((a,b)=>(b.score||0)-(a.score||0));return workspace('ranking','Комиссия / Рейтинг',heading('Рейтинг проектов','Финальная оценка сформирована на основе оценок всех экспертов в соответствии с весами критериев.')+filters([['Все номинации',...new Set(S.projects.map(p=>p.nomination))]])+table(['МЕСТО','НАЗВАНИЕ ПРОЕКТА','НОМИНАЦИЯ','ИТОГОВЫЙ БАЛЛ','ЗАПОЛНЕНО ЭКСПЕРТАМИ','СТАТУС'],ranked.map((p,i)=>row([`<strong class="${i===0?'mint-text':''}">${i+1}</strong>`,projectCell(p),esc(p.nomination),(p.score||0).toFixed(2),`${p.reviews?.length||0}/${p.experts?.length||1}`,badge(p.published?'Опубликован':p.reviews?.length?'Готов к публикации':'Требует проверки')],`data-item data-category="${esc(p.nomination)}"`)))+`<div class="card" style="margin-top:24px"><div class="field-actions"><div class="feature">${icon('users','large')}<div><h3>Доступно комиссии</h3><p>Публикация результатов доступна только членам комиссии.</p></div></div>${button('➤ Опубликовать результаты','publish-results','mint')}</div></div>`,'commission');},
 teacher:()=>workspace('teacher','Кабинет педагога',heading('Мои ученики','Приглашай учеников, следи за их прогрессом и поддерживай участие в конкурсе.',button('＋ Пригласить учеников','teacher-invite','mint sm'))+`<div class="teacher-filters">${['Все ученики','Готовят проект','На проверке','Завершили'].map((t,i)=>`<button class="tab ${i===0?'active':''}" data-tab="${i}" data-key="teacher">${t} ${badge(String(i===0?S.users.length||6:i===1?4:i===2?1:2))}</button>`).join('')}${search('Поиск по имени')}</div>`+table(['УЧЕНИК','КЛАСС','СТАТУС','НАЗВАНИЕ ПРОЕКТА','ПОСЛЕДНЕЕ ДЕЙСТВИЕ'],(S.users.length?S.users.map(u=>[u.profile.name,u.profile.grade+' класс',S.projects.find(p=>p.owner===u.id)?.status||'Готовит проект',S.projects.find(p=>p.owner===u.id)?.name||'Проект ещё не создан']):people).map((p,i)=>row([`<div class="person-cell">${photo(i%2?'teacher':'mentor')}<strong>${esc(p[0])}</strong></div>`,esc(p[1]),badge(p[2]),esc(p[3]),'12 марта 2025'],`data-item data-category="${esc(p[2])}"`)))+`<div class="columns" style="margin-top:25px"><div class="card">${cardTitle('Приглашения','','mail')}${S.mentors.filter(m=>m.status==='Ожидает подтверждения').map(m=>`<div class="setting-row"><div>${esc(S.users.find(u=>u.id===m.owner)?.profile.name||m.owner)}<small style="display:block">Хочет работать с вами</small></div>${button('Принять','accept-invite','mint sm',`data-id="${m.id}"`)}</div>`).join('')||'<p>Все активные приглашения обработаны.</p>'}</div><div class="card">${cardTitle('Сертификат педагога','','trophy')}<p>Вы получите сертификат после завершения участия ваших учеников.</p></div></div>`,'teacher'),
 expert:()=>workspace('expert','Кабинет эксперта',heading('Мои задания','Оценивай проекты, оставляй комментарии и предлагай рекомендации.')+filters([['Все номинации',...new Set(S.projects.map(p=>p.nomination))],['Все статусы','На экспертизе','Оценён','Допущен']])+metrics([[S.projects.length,'Назначено работ'],[S.projects.filter(p=>p.status==='Оценён').length,'Оценено'],[S.projects.filter(p=>p.status==='На экспертизе').length,'В работе'],[S.projects.filter(p=>p.status!=='Оценён').length,'Осталось']])+table(['ПРОЕКТ','УЧАСТНИК','НОМИНАЦИЯ','СТАТУС','НАЗНАЧЕНА','ДЕЙСТВИЕ'],S.projects.map(p=>row([projectCell(p),esc(p.author),esc(p.nomination),badge(p.status),date(p.created),more(p,'evaluate')],`data-item data-category="${esc(p.nomination)}" data-meta="${p.status}"`))),'expert'),
 evaluation:()=>{const p=currentProject();return workspace('evaluation','Оценка проекта',p?`<div class="page-heading"><div>${link('expert','← К списку работ','text-link')}<h2 style="margin-top:12px;font-size:25px">${esc(p.name)}</h2><p>${esc(p.author)} · Номинация: ${esc(p.nomination)}</p></div>${badge('В работе')}</div><form data-form="evaluation"><input type="hidden" name="project" value="${p.id}"><div class="evaluation-layout"><div>${tabs(['Презентация','Исследование','Доп. материалы'],0,'evaluation')}<div class="presentation-preview"><h2>${esc(p.name)}</h2><small style="color:white">Исследовательский проект</small>${photo('bear','Белый медведь')}</div><div class="slide-tools">${button('‹','slide-prev','sm')}<span data-slide>1 / 4</span><span>100%</span>${button('›','slide-next','sm')}</div><div class="slide-thumbs">${['bear','iceberg','whale','ice'].map((n,i)=>`<button type="button" data-action="slide" data-slide-index="${i}" class="${i===0?'active':''}">${photo(n)}</button>`).join('')}</div><div class="notice"><small>Демонстрационный просмотр. Загруженные материалы доступны по ссылкам ниже.</small></div>${p.files?.map(f=>`<a class="text-link" href="/api/files/${f.id}">${icon('download')}${esc(f.name)}</a>`).join('')||''}</div><div class="card evaluation-form"><h3>Критерии оценки</h3><p><small>Итоговая оценка рассчитывается автоматически с учётом весов критериев.</small></p><table class="score-table evaluation-table"><thead><tr><th>КРИТЕРИЙ</th><th>ВЕС, %</th><th>БАЛЛ (0–10)</th><th>ВЗВЕШЕННЫЙ</th></tr></thead><tbody>${cfg().map(([t,w],i)=>`<tr><td>${esc(t)}</td><td>${w}</td><td><input type="number" name="score-${i}" data-weight="${w}" min="0" max="10" step="0.1" value="${[9,8,7,8,9][i]||0}" aria-label="${esc(t)}" required></td><td data-weighted="${i}">${([9,8,7,8,9][i]*w/100).toFixed(2)}</td></tr>`).join('')}<tr><td>Итоговая оценка</td><td>100</td><td></td><td data-evaluation-total>8,15</td></tr></tbody></table><div style="margin-top:22px">${field('Комментарии и рекомендации','comment','','textarea','maxlength="1000" placeholder="Напишите отзыв и рекомендации участнику"')}</div><p class="form-error" role="alert"></p><div class="field-actions"><button class="btn sm" name="mode" value="draft">Сохранить черновик</button><button class="btn mint sm" name="mode" value="submit">➤ Отправить оценку</button></div></div></div></form>`:empty('Нет назначенных проектов'),'expert');},
 admin:()=>workspace('admin','',heading('Обзор конкурса','Текущие показатели и активность участников',`<select class="control" style="width:190px" aria-label="Сезон"><option>Текущий сезон</option></select>`)+metrics([[S.users.filter(u=>u.role==='participant').length,'Участников','users'],[S.projects.length,'Проектов','file'],[12,'Регионов · Демо','pin'],[268,'Школ · Демо','home']])+`<div class="admin-grid"><div class="card">${cardTitle('Участники по регионам',badge('Демо'))}${map()}</div><div class="card">${cardTitle('Очереди модерации',link('distribution','Перейти →','text-link'))}${[['Новые регистрации',S.users.length],['Проекты на проверке',S.projects.filter(p=>p.status==='На проверке').length],['Вопросы от участников',S.messages.length],['Сообщения о нарушениях',0]].map(([t,n],i)=>`<div class="moderation-item"><span>${icon(['user','file','mail','bell'][i])}　${t}</span>${badge(String(n))}</div>`).join('')}</div><div class="card">${cardTitle('Последние действия',link('users','Смотреть все →','text-link'))}${S.projects.slice(0,3).map(p=>`<div class="setting-row"><span>${esc(p.author)}</span><small>${esc(p.status)}</small></div>`).join('')}</div><div class="card"><h3>Экспорт отчётов</h3>${select('Тип отчёта','report',['Сводный отчёт по конкурсу','Список проектов'])}<a href="/api/report?format=csv" class="btn primary wide">${icon('download')} Сформировать отчёт</a></div></div>`,'admin'),
 content:()=>workspace('content','',heading('Управление контентом','Редактируй страницы сайта, новости, видео и баннеры')+tabs(['Страницы','Новости','Видео','Баннеры','Комментарии'],0,'content')+`<div class="columns asymmetric"><div class="card">${cardTitle('Страницы сайта',button('＋ Новая страница','new-content','primary sm'))}${filters([['Все статусы','Опубликовано','Черновик']])}<div data-content-table>${contentTable()}</div></div><aside class="card">${cardTitle('Медиабиблиотека',link('media','Открыть →','text-link'))}<div class="media-library">${['aurora','bear','iceberg','mountain'].map(n=>photo(n)).join('')}</div><div class="media-upload">${icon('upload')}<h3 style="margin:10px 0">Загрузить файлы</h3><small>Изображения, видео, документы</small><label class="btn sm" style="margin-top:12px">Выбрать файл<input type="file" data-upload="media" accept=".png,.jpg,.webp,.pdf,.mp4" hidden></label></div></aside></div>`,'admin'),
 settings:()=>workspace('settings','',heading('Настройки конкурса','Управляй этапами, номинациями и критериями оценки')+tabs(['Этапы конкурса','Номинации','Критерии оценки','Общие настройки'],0,'settings')+`<div class="settings-layout"><div class="card">${cardTitle('Этапы конкурса',button('＋ Добавить этап','add-stage','primary sm'))}<div data-stages>${(S.config.stages||[]).map((t,i)=>`<div class="stage-row"><span>⠿</span><span class="number">${i+1}</span><div><strong>${esc(t)}</strong><small>${i===0?'Подача заявок на участие':'Участие в конкурсе'}</small></div>${badge(i===0?'Активный':'Планируется')}</div>`).join('')}</div></div><form class="card" data-form="settings"><h3>Параметры этапа</h3>${field('Название этапа','stage',S.config.stages?.[0]||'')}${field('Описание','description','Подача заявок на участие в конкурсе.','textarea')}<div class="form-grid">${field('Начало','start','2026-10-01','date')}${field('Конец','end','2026-10-31','date')}</div>${select('Статус','status',['Активный','Планируется','Завершён'],S.config.status)}<p class="form-error" role="alert"></p><button class="btn primary wide">${icon('download')} Сохранить изменения</button></form></div>`,'admin'),
 questions:()=>{const q=S.questions.find(q=>q.id===S.selectedQuestion)||S.questions[0]||{q:'',a:['','','',''],correct:0,topic:'Природа Арктики',difficulty:'Лёгкий',published:false};return workspace('questions','',heading('Банк вопросов','Создавай, редактируй и управляй вопросами для тестов')+`<div class="question-admin"><aside class="card"><h3>Фильтры</h3>${select('Тема','question-topic',['Все темы','Природа Арктики','Научные исследования','Люди Севера','Будущее Арктики'])}${select('Уровень сложности','question-difficulty',['Все уровни','Лёгкий','Средний'])}${select('Статус','question-status',['Все статусы','Опубликован','Черновик'])}${search('Поиск по тексту вопроса')}${button('Показать результаты','question-filter','primary sm')}</aside><div class="card">${cardTitle(`Вопросы (${S.questions.length})`,button('＋ Добавить вопрос','new-question','primary sm'))}${table(['Текст вопроса','Тема','Статус'],S.questions.map(q=>row([`<button class="text-link" data-action="select-question" data-id="${q.id}">${esc(q.q)}</button>`,esc(q.topic),badge(q.published?'Опубликован':'Черновик')],`data-item data-category="${esc(q.topic)}" data-meta="${q.difficulty}"`)))}<div class="notice" style="margin-top:18px">${icon('settings')}Опубликованные вопросы используются при начале новой попытки.</div></div><form class="card" data-form="question"><h3>Редактор вопроса</h3><input type="hidden" name="id" value="${q.id||''}">${select('Тип вопроса','type',['Один правильный ответ'])}${field('Текст вопроса','q',q.q,'textarea','required maxlength="1000"')}${select('Тема','topic',['Природа Арктики','Научные исследования','Люди Севера','Будущее Арктики'],q.topic)}<p>Варианты ответа</p>${q.a.map((a,i)=>`<label class="answer"><input type="radio" name="correct" value="${i}" ${q.correct===i?'checked':''}><input class="control" name="a-${i}" value="${esc(a)}" required aria-label="Вариант ${i+1}"></label>`).join('')}<label class="checkbox"><input type="checkbox" name="published" ${q.published?'checked':''}>Опубликован</label><p class="form-error" role="alert"></p><button class="btn primary wide">Сохранить вопрос</button></form></div>`,'admin');},
 users:()=>publicPage('users',banner('Пользователи<br>и согласия','Управление участниками, ролями и доступами.<br>Безопасные данные в закрытом контуре.',{landscape:false,crumb:false}).replace('</section>',userRoleTabs()+'</section>')+`<div class="container"><div class="users-layout"><aside><h3>Фильтры</h3><div style="margin:15px 0">${search('Поиск по ФИО, email или ID')}</div>${select('Роль','user-role',['Все','Участник','Педагог','Эксперт','Комиссия','Администратор'])}${select('Статус регистрации','user-status',['Все','Активен','Заблокирован'])}${button('Сбросить фильтры','reset-filters','sm')}</aside><div>${cardTitle(`Пользователи (${S.users.length})`,button('＋ Добавить пользователя','add-user','mint sm'))}${table(['Пользователь','Роль','Статус','Согласие','Дата','Действия'],S.users.map(u=>row([`<div class="person-cell">${photo(u.role==='participant'?'portrait':'teacher')}<div><strong>${esc(u.profile.name)}</strong><small style="display:block">${esc(u.email)}</small></div></div>`,badge({participant:'Участник',teacher:'Педагог',expert:'Эксперт',commission:'Комиссия',admin:'Администратор'}[u.role]),badge(u.blocked?'Заблокирован':'Активен'),badge('Подтверждено'),'Демо',button(u.blocked?'Разблокировать':'Заблокировать','block-user','sm',`data-id="${u.id}" data-blocked="${u.blocked?0:1}"`)],`data-item data-category="${u.role}" data-meta="${u.blocked?'Заблокирован':'Активен'}"`)))}</div></div></div>`),
 distribution:()=>workspace('distribution','Администратор',heading('Проекты и распределение','Модерация заявок, допуск к участию и назначение экспертов.',button('＋ Создать проект','admin-create-project','mint sm'))+tabs(['Все проекты','На модерации','Допущены','В работе','Завершены','Отклонены'],0,'distribution')+table(['ПРОЕКТ И УЧАСТНИК','НАПРАВЛЕНИЕ','СТАТУС','ЭКСПЕРТЫ','КОНФЛИКТЫ','ПОДАНО','ДЕЙСТВИЯ'],[projectRows()]),'admin'),
 mailing:()=>publicPage('mailing',banner('Рассылки<br>и интеграции','Управляй коммуникациями с участниками.<br>Информируй, вовлекай, делись возможностями.',{landscape:true,crumb:false})+`<div class="container">${tabs(['Новая рассылка','История рассылок','Шаблоны','Интеграции'],0,'mailing')}<div class="mail-layout"><form data-form="mailing"><h3>1. Выбери канал</h3><input type="hidden" name="channel" value="Email"><div class="channel-options">${[['mail','Email'],['bell','Push'],['users','ВКонтакте']].map(([i,t],j)=>`<button type="button" class="${j===0?'active':''}" data-action="channel" data-channel="${t}">${icon(i)}${t}</button>`).join('')}</div><h3>2. Аудитория</h3>${select('Сегмент','segment',['Участники','Педагоги','Эксперты','Все пользователи'])}<div class="notice">${icon('users')} ${S.users?.length||5} демонстрационных пользователей</div><h3 style="margin:20px 0">3. Сообщение</h3>${field('Тема письма','title','Приглашаем принять участие в конкурсе «Арктика»','text','required maxlength="100" data-email-title')}${field('Текст сообщения','text','Исследуй Север, создавай проекты и открывай новые горизонты!','textarea','required maxlength="2000" data-email-text')}<p class="form-error" role="alert"></p><button class="btn mint wide">Сохранить демо-рассылку →</button><small>Реальные письма не отправляются.</small></form><div><h3 style="margin-bottom:15px">Предпросмотр письма</h3><div class="email-preview"><div class="brand">${icon('globe')} АРКТИКА</div>${photo('mountain')}<div><h3 data-email-preview-title>Удивительная Арктика ждёт твоих идей</h3><p data-email-preview-text>Прими участие во Всероссийском конкурсе для школьников. Исследуй, узнавай, создавай.</p>${link('participate','Узнать подробнее','btn mint sm')}</div></div></div><aside><h3 style="margin-bottom:15px">Интеграции</h3>${[['VK ID','Вход через VK и публикации'],['Email (SMTP)','Для массовых рассылок'],['Zoom / Webinar','Онлайн-мероприятия']].map(([t,p])=>`<div class="integration"><strong>${t}</strong><small>● Не подключено</small><p>${p}</p>${button('Настроить','integration','sm',`data-service="${t}"`)}</div>`).join('')}</aside></div></div>`),
 analytics:()=>workspace('analytics','Администратор',heading('Аналитика и отчёты','Следи за результатами конкурса и формируй отчёты.',`<div>${field('Период','period','2026-10-01','date')}</div>`)+tabs(['Регионы','Школы','Темы','Этапы','Номинации'],0,'analytics')+metrics([[S.users.filter(u=>u.role==='participant').length,'Участников','users'],[S.projects.length,'Проектов','file'],[12,'Регионов · Демо','pin'],[268,'Школ · Демо','home'],[S.users.filter(u=>u.role==='expert').length,'Экспертов','users']]).replace('metric-grid','metric-grid analytics-metrics')+`<div class="chart-layout"><div class="card">${cardTitle('Участники по регионам',badge('Иллюстрация'))}${map()}</div><div class="card"><h3>Проекты по направлениям</h3><div class="donut-layout"><div class="donut"><strong>${S.projects.length}</strong></div><div class="donut-legend">${['Экология','География','Биология','Технологии','Культура','История'].map((t,i)=>`<div><i style="--c:${['#019678','#38b9a2','#74c8b9','#77a1da','#9cafe6','#c4d2f8'][i]}"></i><span>${t}</span><strong>${Math.round(S.projects.filter(p=>p.nomination.includes(t)).length/Math.max(1,S.projects.length)*100)}%</strong></div>`).join('')}</div></div></div><div class="card"><h3>Динамика регистрации <small>Демо</small></h3><svg class="line-chart" viewBox="0 0 500 190" aria-label="Демонстрационный график регистрации"><path d="M20 165H480M20 125H480M20 85H480M20 45H480" stroke="#e0e8e4"/><path d="M20 165 90 156 160 125 230 92 300 95 370 65 480 42V180H20Z" fill="#bce4d8"/><path d="M20 165 90 156 160 125 230 92 300 95 370 65 480 42" fill="none" stroke="#13a382" stroke-width="2"/></svg><div class="chart-labels"><span>Сен</span><span>Окт</span><span>Ноя</span><span>Дек</span></div></div><form class="card" data-form="report"><h3>Отчёты</h3>${select('Шаблон отчёта','type',['Сводный отчёт по конкурсу','Проекты'])}${select('Формат','format',['Excel (.xlsx)','CSV (.csv)'])}<button class="btn primary wide">${icon('download')} Скачать отчёт</button></form></div>`,'admin')
};
